package hexadecimal

import "errors"

var (
    errSyntax = errors.New("invalid hexadecimal syntax")
    errRange  = errors.New("value out of range")
)

// ParseHex converts a hexadecimal string to its decimal equivalent.
func ParseHex(in string) (int64, error) {
    if in == "" {
        return 0, errSyntax
    }
    var n int64
    for _, c := range in {
        var d int64
        switch {
        case c >= '0' && c <= '9':
            d = int64(c - '0')
        case c >= 'a' && c <= 'f':
            d = int64(c-'a') + 10
        case c >= 'A' && c <= 'F':
            d = int64(c-'A') + 10
        default:
            return 0, errSyntax
        }
        // Check for overflow before multiplying and adding
        if n > (math.MaxInt64 - d) / 16 {
            return 0, errRange
        }
        n = n*16 + d
    }
    return n, nil
}

